import {groundSpec} from './ground.mjs?v=zones1';
import {mountPreview} from './spell-preview.mjs?v=pose-speed-1';
import {RUNES,DEFAULT_LOADOUT,validLoadout,spellName} from './loadout.mjs?v=zones1';
import {elementalSpec} from './elements.mjs?v=zones1';
import {forceSpec,wardSpec} from './forces.mjs?v=zones1';
import {describeSpell} from './guide.mjs?v=zones1';
const $=id=>document.getElementById(id),ids=Object.keys(RUNES);
let saved={...DEFAULT_LOADOUT};try{const v=JSON.parse(localStorage.getItem('mage-loadout-v1'));if(validLoadout(v))saved=v;}catch{}
let disposePreview=()=>{};
let selected='qw',branch='w',base='q';
function validSequence(s){return /^[qilwget]{1,3}$/.test(s)}
function spec(seq){return groundSpec(seq)||elementalSpec(seq)||forceSpec(seq)||wardSpec(seq)}
function pool(){return $('mine').checked?Object.values(saved):ids}
function formula(seq){return [...seq].map(k=>`<span style="color:${RUNES[k].color}" title="${RUNES[k].name}">${RUNES[k].icon}</span>`).join('<i>→</i>')}
function recipe(seq){return [...seq].map(k=>RUNES[k].name).join(' → ')}
function attributes(seq){const s=spec(seq),out=[];if(s.projectile)out.push('구체 발사');if(s.moving)out.push('장벽 전진');if(s.falling)out.push('머리 위 낙하');if(s.burn)out.push('화상');if(s.slow)out.push('감속');if(s.echo)out.push('추가 방전');if(s.shock)out.push('주기적 낙뢰');if(s.force)out.push(s.force<0?'당김':'밀침');if(s.push)out.push('밀침');if(s.pull)out.push('당김');if(s.shield)out.push('보호막');if(s.ground)out.unshift('바닥 설치');else if(seq[0]==='e')out.unshift('이동 차단');return out}
function stats(seq){const s=spec(seq);const out=[['충전 시간',(seq.length*1.2).toFixed(1)+'초'],[s.moving?'장벽 이동 거리':s.ground||seq[0]==='e'?'설치 거리':'공격 범위',s.range.toFixed(1)+'m']];if(s.projectile)out.push(['발사 속도',s.speed+'m/s'],['구체 지름',(s.radius*2).toFixed(2)+'m'],['폭발 반경',s.blast.toFixed(2)+'m']);if(s.moving)out.push(['이동 속도',s.speed+'m/s']);if(s.ground)out.push(['장판 반경',s.radius.toFixed(1)+'m'],['유지 시간',s.duration+'초'],['반복 간격',s.interval+'초']);else if(seq[0]==='e')out.push(['내구도',s.hp],['유지 시간',s.duration+'초']);else if(s.force)out.push(['이동시키는 거리',Math.abs(s.force).toFixed(1)+'m']);if(s.slow)out.push(['감속 시간',s.slow+'초']);if(s.burn)out.push(['화상 시간',s.burn+'초']);return out}
function delta(seq){if(groundSpec(seq))return '장판이 들어간 조합은 바닥에 설치합니다. 장판을 더 넣으면 영역과 유지 시간이 늘고, 장벽을 넣으면 유지 시간이 늘어납니다. 다른 재료는 영역 안의 효과를 정합니다.';if(seq.length===1)return '첫 재료가 기본 효과를 정합니다. 밀기는 구체 발사 또는 장벽 전진, 전격은 공격 마법의 머리 위 낙하로 연결됩니다. 장벽＋전격은 낙뢰 장벽입니다.';const prev=seq.slice(0,-1),before=spec(prev),after=spec(seq),fresh=attributes(seq).filter(x=>!attributes(prev).includes(x));const changes=[];if(after.projectile&&before.projectile){if(after.speed!==before.speed)changes.push(`속도 ${before.speed} → ${after.speed}m/s`);if(after.radius!==before.radius)changes.push(`구체 지름 ${(before.radius*2).toFixed(2)} → ${(after.radius*2).toFixed(2)}m`);if(after.blast!==before.blast)changes.push(`폭발 반경 ${before.blast.toFixed(2)} → ${after.blast.toFixed(2)}m`);}if(after.moving&&before.moving&&after.speed!==before.speed)changes.push(`장벽 속도 ${before.speed} → ${after.speed}m/s`);if(after.range>before.range)changes.push(`범위 ${before.range.toFixed(1)} → ${after.range.toFixed(1)}m`);if(after.hp)changes.push(`내구도 ${before.hp} → ${after.hp}`,`유지 ${before.duration} → ${after.duration}초`);if(after.force&&Math.abs(after.force)>Math.abs(before.force||0))changes.push(`이동시키는 거리 ${Math.abs(before.force||0).toFixed(1)} → ${Math.abs(after.force).toFixed(1)}m`);if(after.slow>before.slow&&before.slow)changes.push(`감속 ${before.slow} → ${after.slow}초`);if(fresh.length)changes.push(fresh.join(' · ')+' 추가');else changes.push('새로 추가되는 속성 효과는 없습니다.');return changes.join('<br>')}
function node(seq,root=false){const active=selected===seq,path=selected.startsWith(seq);return `<button class="node ${root?'root-node':''} ${active?'selected':path?'on-path':''}" data-seq="${seq}" aria-pressed="${active}" aria-label="${recipe(seq)} 조합 보기">${root?`<span class="big-icon">${RUNES[seq].icon}</span><b>${spellName(seq)}</b><small>${RUNES[seq].hint}</small>`:`<span class="formula">${formula(seq)}</span><b>${recipe(seq)}</b>`}</button>`}
function select(seq,write=true){if(!validSequence(seq))return;selected=seq;base=seq[0];branch=seq[1]||base;if($('mine').checked&&[...seq].some(k=>!pool().includes(k)))$('mine').checked=false;if(write)history.replaceState(null,'','#'+seq);render()}
function render(){const allowed=pool();document.documentElement.style.setProperty('--accent',RUNES[base].color);
 $('bases').innerHTML=ids.map(k=>`<button class="base" data-base="${k}" aria-pressed="${base===k}" style="--rune:${RUNES[k].color}"><span class="symbol">${RUNES[k].icon}</span><span><b>${RUNES[k].name}</b><small>${RUNES[k].role}</small></span></button>`).join('');
 $('treeTitle').textContent=RUNES[base].name+'에서 시작하는 조합';$('mapNote').textContent=$('mine').checked?'사용 재료: '+Object.values(saved).map(k=>RUNES[k].name).join(' · '):'두 번째 재료의 가지를 선택하면, 그 뒤에 넣을 일곱 재료가 오른쪽에 펼쳐집니다.';
 if(!allowed.includes(branch))branch=allowed[0];
 $('root').innerHTML=node(base,true);$('pairs').innerHTML=allowed.map(k=>node(base+k)).join('');$('triples').innerHTML=allowed.map(k=>node(base+branch+k)).join('');
 $('detailContent').innerHTML=`<div id="spellPreview" class="spell-preview"></div><span class="tier">${selected.length===1?'1륜 · 기본 마법':selected.length+'중 2륜 · 조합 마법'}</span><h2 id="detailTitle">${spellName(selected)}</h2><div class="recipe">${recipe(selected)}</div><div class="stats">${stats(selected).map(([label,value])=>`<div class="stat"><small>${label}</small><b>${value}</b></div>`).join('')}</div><p>${describeSpell(selected)}</p><div class="delta"><strong>${selected.length===1?'조합의 시작':'이전 단계에서 달라지는 점'}</strong>${delta(selected)}</div><p>실제 경기에서는 이 조합에 쓰인 재료를 시작할 때 선택해야 합니다.</p>`;
 disposePreview();disposePreview=mountPreview($('spellPreview'),selected);
 $('shareStatus').textContent='';requestAnimationFrame(drawEdges);
}
function drawEdges(){const svg=$('edges'),graph=$('graph'),rect=graph.getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${rect.width} ${rect.height}`);const pt=(el,side)=>{const r=el.getBoundingClientRect();return{x:(side==='right'?r.right:r.left)-rect.left,y:r.top+r.height/2-rect.top}};const paths=[];function line(a,b,on){const p=pt(a,'right'),q=pt(b,'left'),middle=(p.x+q.x)/2;paths.push(`<path class="${on?'chosen':''}" d="M${p.x},${p.y} C${middle},${p.y} ${middle},${q.y} ${q.x},${q.y}"/>`)}const root=$('root').firstElementChild;for(const pair of $('pairs').children)line(root,pair,pair.dataset.seq===base+branch);const parent=[...$('pairs').children].find(x=>x.dataset.seq===base+branch);if(parent)for(const child of $('triples').children)line(parent,child,child.dataset.seq===selected);svg.innerHTML=paths.join('')}
$('bases').onclick=e=>{const b=e.target.closest('[data-base]');if(b)select(b.dataset.base)};
$('graph').onclick=e=>{const b=e.target.closest('[data-seq]');if(b)select(b.dataset.seq)};
$('mine').onchange=()=>{const allowed=pool();if(!allowed.includes(base))base=allowed[0];select(base+allowed[1])};
$('share').onclick=async()=>{const link=location.href;try{await navigator.clipboard.writeText(link);$('shareStatus').textContent='이 조합의 링크를 복사했습니다.'}catch{$('shareStatus').textContent='주소창의 링크를 복사해 주세요: '+link}};
window.addEventListener('hashchange',()=>select(location.hash.slice(1),false));new ResizeObserver(drawEdges).observe($('graph'));
select(validSequence(location.hash.slice(1))?location.hash.slice(1):'qw',false);
